inline uint32_t luz_tono(float tono) {
    float h = tono / 60; int sector = int(h) % 6;
    int x = int(255 * (1 - fabsf(fmodf(h, 2) - 1)));
    switch (sector) {
        case 0: return Adafruit_NeoPixel::Color(255, x, 0);
        case 1: return Adafruit_NeoPixel::Color(x, 255, 0);
        case 2: return Adafruit_NeoPixel::Color(0, 255, x);
        case 3: return Adafruit_NeoPixel::Color(0, x, 255);
        case 4: return Adafruit_NeoPixel::Color(x, 0, 255);
        default: return Adafruit_NeoPixel::Color(255, 0, x);
    }
}
inline void luz_rango(Adafruit_NeoPixel& tira, float desde, float hasta, float rojo, float verde, float azul, int modo, float valor, float maximo, const char* bloque) {
    if (!luz_lista(tira, bloque)) return;
    int inicio = luz_numero(desde, -32767, 32767, bloque), fin = luz_numero(hasta, -32767, 32767, bloque);
    if (inicio < 0) inicio = 0;
    if (fin >= tira.numPixels()) fin = tira.numPixels() - 1;
    uint32_t color = Adafruit_NeoPixel::Color(luz_numero(rojo, 0, 255, bloque), luz_numero(verde, 0, 255, bloque), luz_numero(azul, 0, 255, bloque));
    float proporcion = maximo > 0 ? fmaxf(0, fminf(1, rb_finite(valor, bloque) / rb_finite(maximo, bloque))) : 0;
    int encendidos = int((fin - inicio + 1) * proporcion);
    if (rb_failed) return;
    for (int i = inicio; i <= fin; i++) {
        uint32_t c = modo == 1 ? luz_tono(fin == inicio ? 0 : 360.0f * (i - inicio) / (fin - inicio)) : modo == 2 ? (i - inicio < encendidos ? Adafruit_NeoPixel::Color(0, 255, 0) : 0) : color;
        tira.setPixelColor(i, c);
    }
    tira.show();
}
inline void luz_invertir(Adafruit_NeoPixel& tira, int inicio, int fin) {
    uint8_t* datos = tira.getPixels();
    while (inicio < fin) {
        for (int c = 0; c < 3; c++) {
            uint8_t color = datos[inicio * 3 + c];
            datos[inicio * 3 + c] = datos[fin * 3 + c]; datos[fin * 3 + c] = color;
        }
        inicio++; fin--;
    }
}
inline void luz_mover(Adafruit_NeoPixel& tira, float lugares, bool circular, const char* bloque) {
    if (!luz_lista(tira, bloque)) return;
    int n = tira.numPixels();
    int paso = circular ? int(fmodf(rb_finite(lugares, bloque), n)) : luz_numero(lugares, -n, n, bloque);
    if (rb_failed) return;
    // Copia bytes sin volver a aplicar brillo. / Copy bytes without rescaling brightness.
    uint8_t* datos = tira.getPixels();
    if (circular) {
        if (paso < 0) paso += n;
        luz_invertir(tira, 0, n - 1); luz_invertir(tira, 0, paso - 1); luz_invertir(tira, paso, n - 1);
    } else if (paso >= 0) {
        for (int i = n - 1; i >= 0; i--) for (int c = 0; c < 3; c++) datos[i * 3 + c] = i >= paso ? datos[(i - paso) * 3 + c] : 0;
    } else {
        for (int i = 0; i < n; i++) for (int c = 0; c < 3; c++) datos[i * 3 + c] = i - paso < n ? datos[(i - paso) * 3 + c] : 0;
    }
    tira.show();
}

def luz_numero(valor, minimo, maximo, bloque):
    return int(max(minimo, min(maximo, rb_finite(valor, bloque))))

def luz_lista(tira, bloque):
    if tira is None:
        rb_fail(bloque, "Inicializa la luz RGB al iniciar")

def luz_inicializar(pin, cantidad, colores, bloque):
    n = luz_numero(cantidad, 1, 21845, bloque)
    tira = neopixel.NeoPixel(Pin(pin), n)
    colores[:] = [(0, 0, 0)] * n
    tira.fill((0, 0, 0))
    tira.write()
    return tira

def luz_mostrar(tira, colores, brillo, bloque):
    luz_lista(tira, bloque)
    for i, color in enumerate(colores):
        tira[i] = tuple(c * brillo // 255 for c in color)
    tira.write()

def luz_tono(tono):
    h = tono / 60
    sector = int(h) % 6
    x = int(255 * (1 - abs(h % 2 - 1)))
    return ((255, x, 0), (x, 255, 0), (0, 255, x), (0, x, 255), (x, 0, 255), (255, 0, x))[sector]

def luz_rango(tira, colores, brillo, desde, hasta, rojo, verde, azul, modo, valor, maximo, bloque):
    luz_lista(tira, bloque)
    inicio = max(0, luz_numero(desde, -32767, 32767, bloque))
    fin = min(len(colores) - 1, luz_numero(hasta, -32767, 32767, bloque))
    color = tuple(luz_numero(c, 0, 255, bloque) for c in (rojo, verde, azul))
    proporcion = max(0, min(1, rb_finite(valor, bloque) / rb_finite(maximo, bloque))) if maximo > 0 else 0
    encendidos = int((fin - inicio + 1) * proporcion)
    for i in range(inicio, fin + 1):
        colores[i] = luz_tono(0 if fin == inicio else 360 * (i - inicio) / (fin - inicio)) if modo == 1 else ((0, 255, 0) if i - inicio < encendidos else (0, 0, 0)) if modo == 2 else color
    luz_mostrar(tira, colores, brillo, bloque)

def luz_mover(tira, colores, brillo, lugares, circular, bloque):
    luz_lista(tira, bloque)
    n = len(colores)
    paso = int(rb_finite(lugares, bloque)) % n if circular else luz_numero(lugares, -n, n, bloque)
    if circular:
        if paso:
            colores[:] = colores[-paso:] + colores[:-paso]
    elif paso > 0:
        colores[:] = [(0, 0, 0)] * paso + colores[:n - paso]
    elif paso < 0:
        colores[:] = colores[-paso:] + [(0, 0, 0)] * -paso
    luz_mostrar(tira, colores, brillo, bloque)
